    ok &= dev.last.flags == 0x18000 && !dev.last.extensible && dev.last.blockAlign == 4 && dev.last.avg == 176400;
    ok &= buf.data[0] == 0 && buf.data[2047] == 0 && buf.data[2048] == 0xAB;
