#endif

static float todB(const float* x)
{
    union { unsigned int i; float f; } ix;
    ix.f = *x;
    ix.i = ix.i & 0x7fffffff;
    return (float)(ix.i * 7.17711438e-7f - 764.6161886f);
}

static void dump(char* out, const float* v, int n, int bark, int dB, i64 off)
